 const [initialPeriod]=useState(()=>({start:validMaintenanceDate(businessDate)?businessDate:'',end:validMaintenanceDate(businessDate)?addMaintenanceDays(businessDate,30):''})),[period,setPeriod]=useState(initialPeriod),[data,setData]=useState<TurnoverList|null>(null),[workspace,setWorkspace]=useState<HotelWorkspace|null>(null),[pending,setPending]=useState<PendingTurnover|null>(initial.pending),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(initial.error),[notice,setNotice]=useState(''),[selected,setSelected]=useState(''),[view,setView]=useState<'open'|'history'|'planning'>('open'),[page,setPage]=useState(0);
