 useEffect(()=>{alive.current=true;const seq=++sequence.current;const cleanup=()=>{alive.current=false;++sequence.current;if(lock.current)callbacks.current.onBusyChange(false)};readTurnovers(tenant,property,initialPeriod.start,initialPeriod.end).then(next=>{if(alive.current&&seq===sequence.current){setData(next.data);setWorkspace(next.workspace)}}).catch(e=>{if(alive.current&&seq===sequence.current)setError(e instanceof Error?e.message:'Unable to load turnover work.')}).finally(()=>{if(alive.current&&seq===sequence.current)setLoading(false)});return()=>cleanup()},[tenant,property,initialPeriod]);
 async function refresh(){const seq=++sequence.current;setData(null);setWorkspace(null);setSelected('');setLoading(true);setError(initial.error);setPage(0);setManualReviewed(false);try{const next=await readTurnovers(tenant,property,period.start,period.end);if(alive.current&&seq===sequence.current){setData(next.data);setWorkspace(next.workspace)}}catch(e){if(alive.current&&seq===sequence.current)setError(e instanceof Error?e.message:'Unable to load turnover work.')}finally{if(alive.current&&seq===sequence.current)setLoading(false)}}
