 async function accepted(status:TurnoverStatus,command:PendingTurnover){const result=validateTurnoverReceipt(status,command);if(!alive.current)return;sessionStorage.removeItem(key);setPending(null);setSelected('');setData(null);setWorkspace(null);setNotice('Turnover request confirmed: '+turnoverStateLabel[result.task.state]+'.');try{const parentRefresh=await callbacks.current.onSaved();if(alive.current&&!parentRefresh?.queueReloadScheduled)await refresh()}catch{if(alive.current)setError('The turnover change is confirmed, but the workspace could not refresh. Refresh the queue before another action.')}}
