 const disabled=externalDisabled||busy||loading||!!initial.error||batchBlocked,selectedTask=data?[...data.open_tasks,...data.closed_tasks].find(t=>t.id===selected):undefined,manualRooms=workspace?.rooms.filter(room=>!data?.open_tasks.some(task=>task.room_id===room.id)&&!workspace.reservations.some(stay=>stay.status==='In house'&&stay.physical_room_id===room.id))??[],rows=data?(view==='history'?data.closed_tasks:data.open_tasks):[],visibleRows=rows.slice(page*25,(page+1)*25);
